binds.biz=()=>{document.querySelectorAll("[data-c]").forEach(i=>i.onchange=()=>{const c=db.catalog.find(x=>x.id===i.dataset.c);c[i.dataset.f]=i.dataset.f==="price"?+i.value:i.value;save();toast("Saved")});
$("#ca").onclick=()=>{if(!$("#cn").value)return;db.catalog.push({id:uid(),name:$("#cn").value,cat:$("#cg").value||"General",price:+$("#cp").value||0});save();render()}};
