views.set=()=>{const s=db.set,f=(k,l,t="text")=>`<label>${l}<input data-s="${k}" type="${t}" value="${esc(s[k])}"></label>`;
return`<h2>Settings &amp; data</h2><div class="card"><h3>Business details (printed on documents)</h3><div class="row">${f("name","Business name")}${f("email","Email")}${phField(s)}</div><div class="row">${f("addr","Address")}${f("reg","Registration no.")}${f("vatNo","VAT no.")}</div>
<div class="row"><label class="f0"><input type="checkbox" id="vo" style="width:auto" ${s.vatOn?"checked":""}> Charge VAT</label>${f("vat","VAT rate %","number")}${f("qn","Next quote no.","number")}${f("in","Next invoice no.","number")}</div>
<div class="row">${f("target","Monthly revenue target (R)","number")}${f("rate","Hourly rate for time billing (R)","number")}${f("costRate","Internal labour cost per hour (R)","number")}${f("cap","Weekly capacity per person (hours)","number")}</div><label>Banking details (shown on invoices)<textarea data-s="bank" rows="3">${esc(s.bank)}</textarea></label><label>Default quotation terms<textarea data-s="terms" rows="3">${esc(s.terms)}</textarea></label></div>
<div class="card"><h3>Logo</h3><p class="mu">Shown in the sidebar, dashboard, printed documents and exports. Upload a larger image for a sharper result.</p><div class="row"><img src="${logo()}" alt="" style="height:56px;border-radius:6px;flex:0 0 auto"><label class="f0" style="margin:0"><input type="file" id="lg" accept="image/*" style="display:none"><button onclick="$('#lg').click()">Upload new logo…</button></label><button class="f0" id="lr">Reset to default</button></div></div>${backupDestUI()}`};

const _bkBind=()=>{
  const val=id=>{const e=$("#"+id);return e?e.value:""};
  const chk=id=>{const e=$("#"+id);return e?e.checked:false};
  if($("#bk_gh_save"))$("#bk_gh_save").onclick=()=>{bkSave({github:{enabled:chk("bk_gh_on"),token:val("bk_gh_token"),owner:val("bk_gh_owner"),repo:val("bk_gh_repo"),branch:val("bk_gh_branch")||"main",path:val("bk_gh_path")||"backups/itt-backup.json",message:val("bk_gh_msg")||"IT-Tech backup {date}",private:chk("bk_gh_priv")}});toast("GitHub settings saved");render()};
  if($("#bk_gh_push"))$("#bk_gh_push").onclick=()=>backupGitHub("push");
  if($("#bk_gh_pull"))$("#bk_gh_pull").onclick=()=>backupGitHub("pull");
  if($("#bk_wd_save"))$("#bk_wd_save").onclick=()=>{bkSave({webdav:{enabled:chk("bk_wd_on"),url:val("bk_wd_url"),user:val("bk_wd_user"),pass:val("bk_wd_pass"),path:val("bk_wd_path")||"/itt-backup.json"}});toast("WebDAV settings saved");render()};
  if($("#bk_wd_push"))$("#bk_wd_push").onclick=()=>backupWebDAV();
  if($("#bk_http_save"))$("#bk_http_save").onclick=()=>{bkSave({http:{enabled:chk("bk_http_on"),url:val("bk_http_url"),method:val("bk_http_method")||"PUT",headerName:val("bk_http_hn"),headerValue:val("bk_http_hv"),contentType:"application/json"}});toast("HTTP settings saved");render()};
  if($("#bk_http_push"))$("#bk_http_push").onclick=()=>backupHTTP();
  if($("#bk_http_pull"))$("#bk_http_pull").onclick=()=>backupPullHTTP();
  if($("#bk_s3_save"))$("#bk_s3_save").onclick=()=>{bkSave({s3:{enabled:chk("bk_s3_on"),endpoint:val("bk_s3_ep"),bucket:val("bk_s3_bucket"),key:val("bk_s3_key")||"itt-backup.json",accessKey:val("bk_s3_ak"),secretKey:val("bk_s3_sk"),region:val("bk_s3_region")||"us-east-1"}});toast("S3 settings saved");render()};
  if($("#bk_s3_push"))$("#bk_s3_push").onclick=()=>backupS3();
};

binds.set=()=>{if(typeof _bkBind==="function")_bkBind();document.querySelectorAll("[data-s]").forEach(i=>i.onchange=()=>{const k=i.dataset.s;db.set[k]=i.type==="number"?+i.value:i.value;save();toast("Saved")});$("#vo").onchange=e=>{db.set.vatOn=e.target.checked;save()};
$("#rs").onchange=e=>importFile(e.target.files[0]);$("#lr").onclick=()=>{delete db.set.logo;save();render();toast("Default logo restored")};$("#lg").onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2e6)return toast("Image is over 2 MB – use a smaller file");const r=new FileReader();r.onload=()=>{db.set.logo=r.result;save();render();toast("Logo updated")};r.readAsDataURL(f)};$("#wp").onclick=async()=>{if(await ask("Erase ALL data? This cannot be undone.",{ok:"Erase everything"})){db=def();save();render()}}};
