/* Directory: staff, contractors, suppliers & partners */
const DCAT={S:"Staff & employees",K:"Contractors & freelancers",C:"Companies, suppliers & partners"};
const DT0={S:["Employee","Permanent employee","Fixed-term employee","Part-time / Casual employee","Intern / Apprentice","Technician","IT support technician","Network technician","Field service technician","Electrician","Mechanic","Auto electrician","Installer","Cabling / Fibre technician","CCTV / Security installer","Solar / PV installer","Engineer","Systems administrator","Software developer","Project manager","Site supervisor / Foreman","General worker / Helper","Driver","Storeman / Stock controller","Office administrator","Sales representative","Bookkeeper / Accountant"],
K:["Contractor","Subcontractor","Freelancer","Consultant","Specialist contractor","Labour broker / Temp staff"],
C:["Supplier","Vendor","Distributor","Wholesaler","Manufacturer / OEM","Reseller / Partner","Service provider","ISP / Telecoms provider","Software / SaaS vendor","Courier / Logistics","Equipment / Tool hire","Vehicle / Fleet service","Calibration / Testing lab","Insurance broker","Bank / Finance","Government / Regulator","Landlord / Property","Training provider","Recruitment agency","E-waste / Recycling","Referral partner"]};
const dTypes=()=>{const o={S:[...DT0.S],K:[...DT0.K],C:[...DT0.C]};(db.dtypes||[]).forEach(t=>{if(o[t.c]&&!Object.values(o).flat().includes(t.n))o[t.c].push(t.n)});return o};
const dCat=t=>{const o=dTypes();return o.S.includes(t)?"S":o.K.includes(t)?"K":"C"};
const isLab=t=>dCat(t)!=="C";

