const labSelect=(id,val,emptyLabel="Me / unassigned")=>{
  const L=labour();
  let o=`<select id="${id}"><option value="">${esc(emptyLabel)}</option>`;
  if(!L.length) o+=`<option value="" disabled>— No technicians in Directory yet —</option>`;
  else o+=L.map(c=>`<option value="${c.id}" ${val===c.id?"selected":""}>${esc(c.name)}${c.type?` (${c.type})`:""}</option>`).join("");
  o+=`</select>`;
  return o;
};
const labHint=()=>labour().length?`<span class="mu">From <a href="#" onclick="go('sup');return false">Directory</a> (staff &amp; freelancers)</span>`:`<span class="mu neg">No assignees yet — <a href="#" onclick="go('sup');return false">add technicians in Directory</a> first</span>`;
