$("#sv").onclick=()=>{if(!$("#n").value.trim())return toast("Enter a name");const o={id:ed&&ed.c.id||uid(),type:$("#ty").value,name:$("#n").value.trim(),spec:$("#sp").value,person:$("#cp").value,rating:+$("#rt").value,status:$("#st").value,notes:$("#nt").value,role:$("#d_role").value};
const g=dCat(o.type);DF.forEach(([,cs,fs])=>{if(cs.includes(g))fs.forEach(([k])=>{const e=$("#d_"+k);if(e)o[k]=e.value})});
const em=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(o.email&&!em.test(o.email))return toast("Email address looks wrong");if(o.email2&&!em.test(o.email2))return toast("Alternative email looks wrong");
if(o.start&&o.end&&o.end<o.start)return toast("End date is before start date");if(o.cstart&&o.cend&&o.cend<o.cstart)return toast("Contract end is before contract start");
phSet(o,phRead());o.cf=cfRead("contacts");const i=db.contacts.findIndex(x=>x.id===o.id);i<0?db.contacts.push(o):db.contacts[i]=mg(db.contacts[i],o);ed=null;save();render();toast("Saved")};
