/* Jobs & service desk */
views.jobs=()=>{const j=ed&&ed.j||{pri:"Normal",status:"New",hrs:1,due:today()},S=["New","Scheduled","In progress","Waiting parts","Done"],fr=labour();
return`<h2>Jobs &amp; service desk</h2><div class="card"><h3>${j.id?"Edit":"Log"} job</h3><div class="row">${inp("jt","Job title",j.title)}<label>Client<select id="jc">${db.clients.map(c=>`<option value="${c.id}" ${j.client===c.id?"selected":""}>${esc(c.name)}</option>`).join("")||"<option value=''>—</option>"}</select></label><label>Assigned to (Directory)${labSelect("ja",j.who||"")}</label><label>Priority${sel("jp",["Low","Normal","High","Urgent"],j.pri)}</label></div>
<div class="row"><label>Status${sel("js",S,j.status)}</label>${inp("jd","Due",j.due,"date")}${inp("jh","Est. hours",j.hrs,"number")}${inp("jn","Notes",j.notes)}<label>Project<select id="jp2"><option value="">— none —</option>${pOpts(j.project)}</select></label></div>${cfForm("jobs",j)}<p>${labHint()}</p><div class="row"><button class="p f0" id="sv">Save job</button> <button class="f0" onclick="go('sup')">Directory</button> <button class="f0" onclick="go('stock')">Issue parts</button> <button class="f0" onclick="go('dispatch')">Dispatches</button></div></div>
<div class="card sc"><table><tr><th>Job</th><th>Client</th><th>Assigned</th><th>Priority</th><th>Due</th><th class="n">Hrs</th><th>Status</th><th></th></tr>${db.jobs.slice().sort((a,b)=>(a.due||"").localeCompare(b.due||"")).map(x=>`<tr><td>${esc(x.title)}<br><span class="mu">${esc(x.notes)}</span>${x.project?` <span class="tag">${esc(pname(x.project))}</span>`:""}</td><td>${esc(cname(x.client))}</td><td>${x.who?esc(vname(x.who)):"Me"}</td><td><span class="tag ${x.pri==="Urgent"?"bad":x.pri==="High"?"wa":""}">${x.pri}</span></td><td class="${x.due&&x.due<today()&&x.status!=="Done"?"neg":""}">${x.due||""}</td><td class="n">${x.hrs}</td><td><select onchange="jobSt('${x.id}',this.value)">${S.map(s=>`<option ${x.status===s?"selected":""}>${s}</option>`).join("")}</select></td><td><button onclick="go('jobs',{j:db.jobs.find(z=>z.id=='${x.id}')})">Edit</button> <button onclick="go('jobs',{tj:'${x.id}'})">Time${x.time&&x.time.length?" ("+x.time.reduce((a,t)=>a+t.hrs,0)+"h)":""}</button> <button onclick="jobQuote('${x.id}')">Quote</button> <button class="d" onclick="delX('jobs','${x.id}')">✕</button></td></tr>`).join("")||"<tr><td colspan=8 class='mu'>No jobs yet. Log call-outs and projects to track them from request to completion.</td></tr>"}</table></div>`};
binds.jobs=()=>{$("#sv").onclick=()=>{if(!$("#jt").value)return toast("Enter a job title");const o={id:ed&&ed.j.id||uid(),title:$("#jt").value,client:$("#jc").value,who:$("#ja").value,pri:$("#jp").value,status:$("#js").value,due:$("#jd").value,hrs:+$("#jh").value||0,notes:$("#jn").value,project:$("#jp2").value};o.cf=cfRead("jobs");const i=db.jobs.findIndex(x=>x.id===o.id);i<0?db.jobs.push(o):db.jobs[i]=mg(db.jobs[i],o);ed=null;save();render();toast("Saved")}};
