let rp={r:"pl",f:new Date().getFullYear()+"-01-01",t:today()};const inR=d=>d>=rp.f&&d<=rp.t,inv_=()=>db.invoices.filter(d=>!["Draft","Void"].includes(d.status)&&inR(d.date));
const REPS={
pl:["Profit & loss",()=>{const L=db.ledger.filter(l=>inR(l.date)),o={};L.forEach(l=>{const k=l.type+"|"+l.cat;o[k]=(o[k]||0)+l.amount});const rows=Object.entries(o).map(([k,v])=>{const a=k.split("|");return[a[0]==="income"?"Income":"Expense",a[1],v]}).sort((a,b)=>b[0].localeCompare(a[0])||b[2]-a[2]);rows.push(["","Net profit",sum(L.filter(l=>l.type==="income"))-sum(L.filter(l=>l.type==="expense"))]);return{cols:[["Type"],["Category"],["Amount",1]],rows}}],
cash:["Cash flow by month",()=>{const o={};db.ledger.filter(l=>inR(l.date)).forEach(l=>{const m=month(l.date),a=o[m]=o[m]||[0,0];a[l.type==="income"?0:1]+=l.amount});let c=0;return{cols:[["Month"],["Money in",1],["Money out",1],["Net",1],["Running total",1]],rows:Object.keys(o).sort().map(m=>{c+=o[m][0]-o[m][1];return[m,o[m][0],o[m][1],o[m][0]-o[m][1],c]})}}],
cl:["Sales by client",()=>{const o={};inv_().forEach(d=>{const t=tot(d),a=o[d.client]=o[d.client]||[0,0,0];a[0]+=t.t;a[1]+=t.paid;a[2]+=t.bal});return{cols:[["Client"],["Billed",1],["Paid",1],["Balance",1]],rows:Object.entries(o).sort((a,b)=>b[1][0]-a[1][0]).map(([k,a])=>[cname(k),...a])}}],
it:["Sales by service / item",()=>{const o={};inv_().forEach(d=>d.items.forEach(i=>{const a=o[i.desc]=o[i.desc]||[0,0];a[0]+=i.qty;a[1]+=i.qty*i.price*(1-(i.disc||0)/100)}));return{cols:[["Item"],["Quantity"],["Revenue (excl. extras)",1]],rows:Object.entries(o).sort((a,b)=>b[1][1]-a[1][1]).map(([k,a])=>[k,...a])}}],
vat:["VAT by month",()=>{const o={},r=db.set.vat;db.ledger.filter(l=>l.vat&&inR(l.date)).forEach(l=>{const m=month(l.date),a=o[m]=o[m]||[0,0],v=l.amount*r/(100+r);a[l.type==="income"?0:1]+=v});return{cols:[["Month"],["Output VAT",1],["Input VAT",1],["Payable",1]],rows:Object.keys(o).sort().map(m=>[m,o[m][0],o[m][1],o[m][0]-o[m][1]])}}],
age:["Debtors ageing by client",()=>{const o={};db.invoices.forEach(d=>{if(["Paid","Void","Draft"].includes(ist(d)))return;const n=Math.floor((Date.now()-new Date(d.due||d.date))/864e5),a=o[d.client]=o[d.client]||[0,0,0,0,0];a[n<=0?0:n<=30?1:n<=60?2:n<=90?3:4]+=tot(d).bal});return{cols:[["Client"],["Current",1],["1–30",1],["31–60",1],["61–90",1],["90+",1]],rows:Object.entries(o).map(([k,a])=>[cname(k),...a])}}],
pipe:["Quote pipeline",()=>{const o={};db.quotes.filter(d=>inR(d.date)).forEach(d=>{const s=qst(d),a=o[s]=o[s]||[0,0];a[0]++;a[1]+=tot(d).t});return{cols:[["Status"],["Quotes"],["Value",1]],rows:Object.entries(o).map(([k,a])=>[k,...a])}}],
sup:["Purchases by supplier",()=>{const o={};db.pos.filter(p=>inR(p.date)&&p.status!=="Draft").forEach(p=>o[p.sup]=(o[p.sup]||0)+poT(p));return{cols:[["Supplier"],["Spend",1]],rows:Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[vname(k),v])}}],
stk:["Stock valuation",()=>({cols:[["Item"],["Qty"],["Cost value",1],["Retail value",1]],rows:db.stock.map(s=>[s.name,s.qty,s.qty*s.cost,s.qty*s.price])})],
tm:["Hours logged by job",()=>({cols:[["Job"],["Client"],["Hours"],["Unbilled hrs"]],rows:db.jobs.filter(j=>(j.time||[]).length).map(j=>[j.title,cname(j.client),sum(j.time,t=>t.hrs),sum(j.time.filter(t=>!t.b),t=>t.hrs)])})]};
views.rep=()=>{const x=REPS[rp.r][1]();return`<h2>Reports</h2><div class="card"><div class="row"><label>Report<select id="rr">${Object.entries(REPS).map(([k,v])=>`<option value="${k}" ${rp.r===k?"selected":""}>${v[0]}</option>`).join("")}</select></label>${inp("rf","From",rp.f,"date")}${inp("rt","To",rp.t,"date")}<button class="f0" id="rpp">Print / PDF</button><button class="f0" id="rpc">CSV</button><button class="f0" id="rpx">Excel</button></div>
<div class="sc"><table><tr>${x.cols.map(c=>`<th class="${c[1]?"n":""}">${c[0]}</th>`).join("")}</tr>${x.rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${x.cols[i][1]?"n":""}">${x.cols[i][1]?R(v):esc(v)}</td>`).join("")}</tr>`).join("")||"<tr><td class='mu'>No data in this period.</td></tr>"}</table></div></div>`};
binds.rep=()=>{const x=REPS[rp.r][1](),h=()=>x.rows.map(r=>Object.fromEntries(x.cols.map((c,i)=>[c[0],r[i]])));
$("#rr").onchange=e=>{rp.r=e.target.value;render()};$("#rf").onchange=e=>{rp.f=e.target.value;render()};$("#rt").onchange=e=>{rp.t=e.target.value;render()};
$("#rpc").onclick=()=>csvOut(rp.r+"-report.csv",h());
$("#rpx").onclick=()=>{const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(h()),"Report");XLSX.writeFile(wb,rp.r+"-report.xlsx")};
$("#rpp").onclick=()=>{$("#doc").innerHTML=docCss()+`<img src="${logo()}" alt="" style="height:56px;border-radius:6px"><h2>${REPS[rp.r][0]}</h2><p>${rp.f} to ${rp.t}</p>`+$("#app table").outerHTML;window.print()}};

