window.schedSync=()=>{if(!fsRoot)return;clearTimeout(fsT);fsT=setTimeout(()=>syncNow(),3000)};
const fsOpen=async h=>{fsH=h;fsRoot=await h.getDirectoryHandle("IT-Tech-Business-Manager",{create:true});fsInfo.name=h.name+" / IT-Tech-Business-Manager";fsSig.clear()};
window.fsConnect=async()=>{try{const h=await showDirectoryPicker({mode:"readwrite",id:"ittbm"});await fsOpen(h);try{await idb("set",h)}catch(e){}await syncNow(1)}catch(e){if(e.name!=="AbortError")toast("Could not use that folder – pick a new empty folder, not a system folder")}render()};
window.fsReconnect=async()=>{try{if((await fsH.requestPermission({mode:"readwrite"}))==="granted"){await fsOpen(fsH);await syncNow(1)}}catch(e){toast("Permission not granted")}render()};
window.fsOff=()=>{fsRoot=null;fsH=null;fsSig.clear();idb("del").catch(()=>{});render()};
window.fsRestore=async()=>{try{const f=await(await(await fsRoot.getDirectoryHandle("Data")).getFileHandle("backup.json")).getFile(),j=JSON.parse(await f.text());if(!await ask("Replace all current data with the copy in the folder?",{ok:"Replace",danger:false}))return;db={...def(),...j};save();render();toast("Restored from folder")}catch(e){toast("No backup found in the folder yet")}};
window.fsZip=()=>{dl("IT-Tech-Business-Manager-"+today()+".zip",zip(buildFiles()),"application/zip");db.set.lastBackup=today();save()};
window.fsShare=async()=>{const f=new File([zip(buildFiles())],"IT-Tech-Business-Manager-"+today()+".zip",{type:"application/zip"});if(navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:"IT-Tech Business Manager data"})}catch(e){}}else toast("Sharing files isn't supported here – use Download ZIP")};
views.fs=()=>{const on=!!fsRoot,re=fsH&&!fsRoot;return`<h2>Local folder &amp; sync</h2><div class="card"><h3>Network &amp; GitHub backups</h3><p class="mu">GitHub, WebDAV/NAS, HTTPS endpoints and S3-compatible storage are configured under System Backups.</p><button class="p f0" onclick="go('set')">Open backup destinations</button></div><div class="card"><h3>Status</h3>${on?`<p><span class="tag ok">Connected</span> Saving to <b>${esc(fsInfo.name)}</b><br>Last sync: ${esc(fsInfo.at||"–")} · ${fsInfo.n||0} files${fsInfo.err?`<br><span class="neg">${esc(fsInfo.err)}</span>`:""}</p>`:re?`<p><span class="tag wa">Reconnect needed</span> The browser needs your permission again to write to <b>${esc(fsInfo.name)}</b>.${fsInfo.err?`<br><span class="neg">${esc(fsInfo.err)}</span>`:""}</p>`:`<p><span class="tag">Not connected</span> ${fsSup?"Choose a folder. The app creates its directory there and keeps it updated automatically a few seconds after every change.":"This browser can't write to a chosen folder, so use the ZIP options below."}</p>`}
<div class="row">${fsSup?(on?`<button class="p f0" onclick="syncNow(1)">Sync now</button><button class="f0" onclick="fsRestore()">Restore from folder</button><button class="f0" onclick="fsOff()">Disconnect</button>`:re?`<button class="p f0" onclick="fsReconnect()">Reconnect folder</button><button class="f0" onclick="fsOff()">Forget folder</button>`:`<button class="p f0" onclick="fsConnect()">Choose folder &amp; create directory</button>`):""}<button class="f0" onclick="fsZip()">Download folder as ZIP</button>${navigator.canShare?`<button class="f0" onclick="fsShare()">Share / save ZIP</button>`:""}</div></div>
<div class="card"><h3>What gets saved</h3><pre class="mu" style="margin:0">IT-Tech-Business-Manager/
  README.txt
  Data/            backup.json, all-data.xlsx, CSVs (ledger, clients, quotes, invoices, jobs, directory, inventory, purchase orders, calendar notes)
  Clients/&lt;name&gt;/   Quotations/, Invoices/, Statement.html
  Purchase-Orders/ one page per order
  Reports/         every report as CSV
  Backups/         a dated backup each day
  Logo/            your logo</pre></div>
<div class="card"><h3>Which devices can do what</h3><p><b>Windows, macOS, Linux, ChromeOS</b> in Chrome, Edge, Opera or Brave: pick a folder and it syncs automatically. Choose a new empty folder, for example inside Documents. Chrome refuses Downloads and system folders.</p><p><b>Android, iPhone, iPad, and Firefox or Safari anywhere:</b> browsers don't allow writing to a folder you choose. Use <i>Download folder as ZIP</i> or <i>Share / save ZIP</i>, which lets you save to Files, Drive or iCloud. The ZIP unpacks to exactly the same folders.</p><p class="mu">Open the .html files in any browser and print to PDF. To restore from a ZIP, unzip it and use Settings &amp; data &gt; Restore from backup with Data/backup.json.</p></div>`};
(async()=>{if(!fsSup)return;try{const h=await idb("get");if(!h)return;fsH=h;fsInfo.name=h.name+" / IT-Tech-Business-Manager";if((await h.queryPermission({mode:"readwrite"}))==="granted"){await fsOpen(h);syncNow()}if(page==="fs")render()}catch(e){}})();

/* ===== v5: multiple contact numbers + in-app dialogs ===== */
const PL=["Mobile","Work","Home","WhatsApp","Office","Other"];
const phs=o=>((o&&o.phones&&o.phones.length)?o.phones:(o&&o.phone?[{l:"Mobile",n:o.phone}]:[])).filter(p=>p&&p.n);
const phTxt=o=>phs(o).map(p=>p.n).join(" · ");
const waNum=o=>{const l=phs(o);return(l.find(p=>/whats/i.test(p.l))||l.find(p=>/mobile/i.test(p.l))||l[0]||{}).n||""};
const pf=o=>cfx({...o,phone:phs(o).map(p=>p.n).join(" / "),phones:phs(o).map(p=>p.l+": "+p.n).join("; ")});
const phRow=p=>`<div class="phr row" style="margin:0 0 6px"><label style="flex:0 0 118px;margin:0"><select class="phl" aria-label="Number type">${PL.map(x=>`<option ${x===p.l?"selected":""}>${x}</option>`).join("")}</select></label><label style="margin:0"><input class="phn" type="tel" inputmode="tel" autocomplete="off" placeholder="e.g. 082 123 4567" aria-label="Contact number" value="${esc(p.n)}"></label><button type="button" class="d f0" onclick="phDel(this)" aria-label="Remove number">✕</button></div>`;
const phField=o=>{const l=phs(o);return`<div class="phf" style="flex:2;min-width:270px"><span class="mu" style="font-size:12px">Contact numbers</span><div class="phc">${(l.length?l:[{l:"Mobile",n:""}]).map(phRow).join("")}</div><button type="button" class="f0" onclick="phAdd(this)">+ Add another number</button></div>`};
window.phAdd=b=>{const c=b.parentNode.querySelector(".phc");c.insertAdjacentHTML("beforeend",phRow({l:"Mobile",n:""}));c.lastElementChild.querySelector("input").focus()};
window.phDel=b=>{const f=b.closest(".phf"),c=b.closest(".phc"),r=b.closest(".phr");if(c.children.length>1)r.remove();else r.querySelector("input").value="";f.dispatchEvent(new Event("change",{bubbles:true}))};
const phRead=root=>[...(root||document).querySelectorAll(".phr")].map(r=>({l:r.querySelector(".phl").value,n:r.querySelector(".phn").value.trim()})).filter(p=>p.n);
const phSet=(o,l)=>{o.phones=l;o.phone=l[0]?l[0].n:""};
const _sb=binds.set;binds.set=()=>{_sb();const f=$(".phf");if(f)f.addEventListener("change",()=>{phSet(db.set,phRead(f));save();toast("Contact numbers saved")})};

function ask(msg,o={}){const inp_=o.input!=null;return new Promise(res=>{const el=document.createElement("div");el.className="ov";el.innerHTML=`<div class="card dlg" role="dialog" aria-modal="true"><p style="margin:0 0 10px">${esc(msg)}</p>${inp_?`<input id="mi" value="${esc(o.input)}">`:""}<div class="row" style="justify-content:flex-end;margin:12px 0 0"><button class="f0" id="mc">Cancel</button><button class="f0 ${inp_||o.danger===false?"p":"dg"}" id="mo">${esc(o.ok||(inp_?"Save":"Delete"))}</button></div></div>`;document.body.appendChild(el);
const no=inp_?null:false,done=v=>{document.removeEventListener("keydown",kd,true);el.remove();res(v)},kd=e=>{if(e.key==="Escape"){e.stopPropagation();done(no)}if(e.key==="Enter"&&e.target.tagName!=="BUTTON"){e.preventDefault();done(inp_?$("#mi").value:true)}};
document.addEventListener("keydown",kd,true);$("#mc").onclick=()=>done(no);$("#mo").onclick=()=>done(inp_?$("#mi").value:true);el.onclick=e=>{if(e.target===el)done(no)};($("#mi")||$("#mo")).focus()})}
const askText=(m,d="")=>ask(m,{input:d});
const nativePrint=window.print.bind(window);
window.print=()=>{const t=document.title,el=document.createElement("div");el.className="ov";el.style.alignItems="flex-start";
el.innerHTML=`<div class="card" style="width:min(900px,96vw);max-height:94vh;overflow:auto;margin-top:2vh;background:#fff;color:#000"><div class="row" style="position:sticky;top:0;background:#fff;padding:4px 0 8px;margin:0 0 8px;z-index:1"><button class="p f0" id="pp">Print / Save as PDF</button><button class="f0" id="pcl" style="color:#000">Close</button></div><div id="pv">${$("#doc").innerHTML}</div></div>`;document.body.appendChild(el);
const close=()=>{document.removeEventListener("keydown",kd,true);el.remove()},kd=e=>{if(e.key==="Escape")close()};document.addEventListener("keydown",kd,true);
$("#pcl").onclick=close;el.onclick=e=>{if(e.target===el)close()};$("#pp").onclick=()=>{const o=document.title;document.title=t;nativePrint();document.title=o}};

/* ===== v6: custom fields, document templates, appearance ===== */
