const PF=[
["People & responsibility",[["lead","Technical lead","pe"],["acct","Account / sales manager","pe"],["qa","Quality reviewer / approver","pe"],["team","Project team members","mp"],["sponsor","Client sponsor / decision maker","t"],["ccontact","Client contact person","t"],["cemail","Client contact email","t"]]],
["Vendors & suppliers",[["vendor","Primary vendor","ve"],["vendors","Other vendors","mv"],["supplier","Primary supplier","su"],["suppliers","Other suppliers","ms"],["subs","Subcontractors / freelancers","mf"]]],
["Classification & site",[["code","Project code","t"],["cat","Category","s:Network,Server,Cloud,Hardware,Software,Wireless,Industry 4.0,Support,Other"],["sector","Sector","s:Residential,Commercial,Industrial,Agricultural"],["delivery","Delivery method","s:On-site,Remote,Hybrid"],["site","Site / address","a"],["tags","Tags","t"]]],
["Commercial",[["po","Client PO / contract number","t"],["terms","Payment terms","s:Due on receipt,7 days,14 days,30 days,60 days"],["margin","Target margin %","n"],["estH","Estimated total hours","n"],["warranty","Warranty (months)","n"],["sla","SLA","s:None,4 hours,Next business day,48 hours"],["cc","Cost centre / GL code","t"],["permits","Permits required","c"],["induct","Site induction required","c"],["insured","Insurance cover confirmed","c"]]],
["Schedule & governance",[["phase","Phase","s:Initiation,Planning,Execution,Monitoring,Closure"],["rlevel","Overall risk level","s:Low,Medium,High"],["approval","Approval status","s:Not required,Pending,Approved,Rejected"],["astart","Actual start","d"],["aend","Actual finish","d"],["review","Next review date","d"],["scope","Scope summary","a"],["deliv","Key deliverables","a"],["assump","Assumptions & constraints","a"],["lessons","Lessons learned","a"],["inotes","Internal notes","a"]]]];
const dirOpts=t=>db.contacts.filter(c=>c.type===t).map(c=>[c.id,c.name]),peOpts=()=>[["me","Me"],...dirOpts("Freelancer")];
const chips=(k,l,o,sel)=>`<div data-chip="${k}" style="flex:2;min-width:260px"><span class="mu" style="font-size:calc(var(--fs)*.85)">${l}</span><div>${o.map(x=>`<label style="display:inline-flex;gap:4px;margin:2px 12px 2px 0;align-items:center;font-size:var(--fs)"><input type="checkbox" style="width:auto" value="${esc(x[0])}" ${(sel||[]).includes(x[0])?"checked":""}> ${esc(x[1])}</label>`).join("")||'<span class="mu">None yet – add them in the Directory.</span>'}</div></div>`;
const pfCtl=(f,v)=>{const k=f[0],l=f[1],t=f[2].split(":"),ty=t[0],id="px_"+k,x=v==null?"":v,opt=(a,s)=>a.map(o=>`<option value="${esc(o[0])}" ${o[0]===s?"selected":""}>${esc(o[1])}</option>`).join("");
if(ty==="a")return`<label style="flex:2;min-width:240px">${l}<textarea id="${id}" rows="2">${esc(x)}</textarea></label>`;
if(ty==="s")return`<label>${l}<select id="${id}"><option value=""></option>${t[1].split(",").map(o=>`<option ${o===x?"selected":""}>${o}</option>`).join("")}</select></label>`;
if(ty==="c")return`<label class="f0"><input type="checkbox" id="${id}" style="width:auto" ${x?"checked":""}> ${l}</label>`;
if(ty==="ve"||ty==="su")return`<label>${l}<select id="${id}"><option value="">— none —</option>${opt(dirOpts(ty==="ve"?"Vendor":"Supplier"),x)}</select></label>`;
if(ty==="pe")return`<label>${l}<select id="${id}"><option value="">— not assigned —</option>${opt(peOpts(),x)}</select></label>`;
if(ty==="mv")return chips(k,l,dirOpts("Vendor"),x);if(ty==="ms")return chips(k,l,dirOpts("Supplier"),x);if(ty==="mf")return chips(k,l,dirOpts("Freelancer"),x);if(ty==="mp")return chips(k,l,peOpts(),x);
return`<label>${l}<input id="${id}" type="${ty==="n"?"number":ty==="d"?"date":"text"}" ${ty==="n"?'step="any"':""} value="${esc(x)}"></label>`};
const pfForm=e=>`<div style="margin:6px 0"><b>More project information</b> <span class="mu">(all optional)</span></div>`+PF.map(([sec,fs],i)=>`<details ${i<2?"open":""} style="margin:8px 0"><summary><b>${sec}</b></summary><div class="row" style="margin-top:8px">${fs.map(f=>pfCtl(f,e[f[0]])).join("")}${i===0?phField({phones:e.cphones}).replace("Contact numbers","Client contact numbers"):""}</div></details>`).join("");
const pfRead=()=>{const r={};PF.forEach(([s,fs])=>fs.forEach(([k,l,t])=>{const ty=t.split(":")[0],el=$("#px_"+k);if(["mv","ms","mf","mp"].includes(ty))r[k]=[...document.querySelectorAll('[data-chip="'+k+'"] input:checked')].map(i=>i.value);else if(el)r[k]=ty==="c"?el.checked:ty==="n"&&el.value!==""?+el.value:el.value}));return r};
const pn=id=>id==="me"?"Me":vname(id),pcard=id=>{const c=db.contacts.find(x=>x.id===id);return c?[c.name,phTxt(c),c.email].filter(Boolean).join(" · "):""};
const pfShow=p=>PF.map(([sec,fs])=>{const rows=[];fs.forEach(([k,l,t])=>{const ty=t.split(":")[0],v=p[k];if(v===undefined||v===""||v===false||(Array.isArray(v)&&!v.length))return;
rows.push([l,ty==="c"?"Yes":ty==="ve"||ty==="su"?(pcard(v)||"(removed from Directory)"):ty==="pe"?pn(v):ty==="mv"||ty==="ms"||ty==="mf"?(v.map(pcard).filter(Boolean).join("\n")||"(removed from Directory)"):ty==="mp"?v.map(pn).join(", "):v])});
if(sec==="People & responsibility"&&phs({phones:p.cphones}).length)rows.push(["Client contact numbers",phTxt({phones:p.cphones})]);
if(sec==="Vendors & suppliers"){const po=db.pos.filter(x=>x.proj===p.id&&x.status!=="Draft");if(po.length)rows.push(["Purchase orders on this project",po.length+" · "+R(sum(po,poT))])}return[sec,rows]}).filter(x=>x[1].length);
const pfCheck=ex=>{const g=k=>{const e=$("#px_"+k);return e?e.value.trim():""},n=k=>g(k)===""?null:+g(k);
if(g("cemail")&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(g("cemail")))return"Client contact email doesn't look right";
const m=n("margin");if(m!==null&&(m<-100||m>100))return"Target margin must be between -100 and 100";
for(const[k,l]of[["estH","Estimated total hours"],["warranty","Warranty months"]]){const v=n(k);if(v!==null&&v<0)return l+" can't be negative"}
if(g("astart")&&g("aend")&&g("aend")<g("astart"))return"Actual finish can't be before actual start";
const st=v_("pp_a"),en=v_("pp_e");if(st&&en&&en<st)return"End date can't be before start date";
const c=g("code").toLowerCase();if(c&&db.projects.some(p=>(p.code||"").toLowerCase()===c&&(!ex||p.id!==ex.id)))return"Project code "+g("code")+" is already used by another project";
return""};
const pInfoCard=p=>{const S=pfShow(p);return S.length?`<div class="card"><h3>Project information</h3>${S.map(([sec,rows])=>`<h4 style="margin:10px 0 4px">${sec}</h4><table>${rows.map(r=>`<tr><td class="mu" style="width:34%">${esc(r[0])}</td><td>${esc(r[1]).replace(/\n/g,"<br>")}</td></tr>`).join("")}</table>`).join("")}${p.supplier?`<div class="row" style="margin-top:10px"><button class="f0" id="ov_po">New purchase order to ${esc(vname(p.supplier))}</button></div>`:""}</div>`:`<div class="card mu">No extra information yet. Use <b>Edit details</b> to add vendors, suppliers, responsible people, site, commercial and governance details.</div>`};
const _ov=TABS.overview,_tov=TB.overview;TABS.overview=p=>_ov(p)+pInfoCard(p);
