/* Field dispatches – urgent / call-out jobs */
views.dispatch=()=>{
  const D=db.jobs.filter(j=>j.pri==="Urgent"||j.dispatch);
  const e=ed&&ed.j&&(ed.j.dispatch||ed.j.pri==="Urgent")?ed.j:{pri:"Urgent",status:"New",hrs:1,due:today(),dispatch:true};
  return`<h2>Field Dispatches &amp; Call-outs</h2>
  <div class="grid"><div class="card kpi"><span>Open dispatches</span><b>${D.filter(j=>j.status!=="Done").length}</b></div>
  <div class="card kpi"><span>Due today</span><b>${D.filter(j=>j.due===today()&&j.status!=="Done").length}</b></div>
  <div class="card kpi"><span>Overdue</span><b class="neg">${D.filter(j=>j.due&&j.due<today()&&j.status!=="Done").length}</b></div>
  <div class="card kpi"><span>Technicians in Directory</span><b>${labour().length}</b></div></div>
  <div class="card"><h3>${e.id?"Edit":"New"} dispatch / call-out</h3>
  <div class="row">${inp("dj_t","Title",e.title)}<label>Client<select id="dj_c"><option value="">—</option>${db.clients.map(c=>`<option value="${c.id}" ${e.client===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></label>
  <label>Assigned to (Directory)${labSelect("dj_w",e.who||"")}</label>
  ${inp("dj_d","Due",e.due||today(),"date")}${inp("dj_h","Est. hours",e.hrs||1,"number")}</div>
  <p>${labHint()}</p>
  <div class="row">${inp("dj_n","Notes / site access",e.notes||"")}
  <label>Use stock parts<select id="dj_stk"><option value="">— none —</option>${db.stock.filter(x=>x.qty>0).map(x=>`<option value="${x.id}">${esc(x.name)} (${x.qty})</option>`).join("")}</select></label>
  ${inp("dj_sq","Parts qty",1,"number")}
  <button class="p f0" id="dj_sv">Save dispatch</button></div></div>
  <div class="card sc"><table><tr><th>Title</th><th>Client</th><th>Due</th><th>Assigned</th><th>Status</th><th></th></tr>
  ${D.map(j=>`<tr><td>${esc(j.title)}</td><td>${esc(cname(j.client))}</td><td class="${j.due&&j.due<today()&&j.status!=="Done"?"neg":""}">${j.due||""}</td><td>${esc(who(j.who))}</td>
  <td><select onchange="jobSt('${j.id}',this.value)">${["New","Scheduled","In progress","Waiting parts","Done"].map(s=>`<option ${j.status===s?"selected":""}>${s}</option>`).join("")}</select></td>
  <td><button onclick="go('dispatch',{j:db.jobs.find(z=>z.id=='${j.id}')})">Edit</button> <button class="d" onclick="delX('jobs','${j.id}')">✕</button></td></tr>`).join("")||"<tr><td colspan=6 class='mu'>No dispatches yet. Urgent jobs also appear here.</td></tr>"}</table></div>
  <div class="card"><p class="mu">Workflow: Directory (technicians) → Dispatch → Job status → Issue parts from Inventory → Log time → Invoice.</p>
  <button onclick="go('sup')">Directory</button> <button onclick="go('jobs')">All jobs</button> <button onclick="go('work')">Workspace</button> <button onclick="go('stock')">Inventory</button></div>`;
};
binds.dispatch=()=>{$("#dj_sv").onclick=()=>{if(!$("#dj_t").value)return toast("Enter a title");
  const o={id:ed&&ed.j&&ed.j.id||uid(),title:$("#dj_t").value,client:$("#dj_c").value,who:$("#dj_w").value,pri:"Urgent",status:(ed&&ed.j&&ed.j.status)||"New",due:$("#dj_d").value,hrs:+$("#dj_h").value||1,notes:$("#dj_n").value,dispatch:true,time:(ed&&ed.j&&ed.j.time)||[],cf:{}};
  const i=db.jobs.findIndex(x=>x.id===o.id);if(i<0)db.jobs.push(o);else db.jobs[i]={...db.jobs[i],...o};
  const sid=$("#dj_stk")&&$("#dj_stk").value,sq=+$("#dj_sq").value||0;
  if(sid&&sq>0){stkMove(sid,"Issue",sq,{job:o.id,notes:"Dispatch parts – "+o.title,ref:o.title});toast("Parts issued from stock")}
  ed=null;save();render();toast("Dispatch saved")}};


