/* Hardware lifecycle – assets + stock bridge */
views.hwlife=()=>{
  const stages=["Ordered","In stock","Deployed","In repair","Warranty","Retired"];
  const e=ed&&ed.hw||{stage:"In stock",date:today(),cost:0};
  const rows=[
    ...db.assets.map(a=>({id:a.id,src:"assets",name:a.name,stage:a.stage||"Deployed",client:a.client||"",date:a.date,cost:a.cost,serial:a.serial||""})),
    ...db.stock.filter(s=>(s.track||s.serial||s.qty>0)).map(s=>({id:s.id,src:"stock",name:s.name,stage:s.stage||"In stock",client:"",date:"",cost:s.cost,serial:s.sku||""}))
  ];
  return`<h2>Hardware Lifecycle Manager</h2>
  <div class="grid"><div class="card kpi"><span>Tracked items</span><b>${rows.length}</b></div>
  <div class="card kpi"><span>Deployed</span><b>${rows.filter(r=>r.stage==="Deployed").length}</b></div>
  <div class="card kpi"><span>In repair</span><b>${rows.filter(r=>r.stage==="In repair").length}</b></div>
  <div class="card kpi"><span>Asset cost</span><b>${R(sum(db.assets,a=>a.cost))}</b></div></div>
  <div class="card"><h3>Register / update hardware</h3>
  <div class="row">${inp("hw_n","Name / model",e.name)}${inp("hw_s","Serial / asset tag",e.serial||"")}
  <label>Stage${sel("hw_st",stages,e.stage||"In stock")}</label>
  <label>Client (if deployed)<select id="hw_c"><option value="">—</option>${db.clients.map(c=>`<option value="${c.id}" ${e.client===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></label>
  ${inp("hw_cost","Cost",e.cost||0,"number")}${inp("hw_d","Date",e.date||today(),"date")}</div>
  <div class="row"><button class="p f0" id="hw_sv">Save to Fixed Assets</button> <button class="f0" onclick="go('assets')">Open Fixed Assets</button> <button class="f0" onclick="go('stock')">Open Inventory</button></div></div>
  <div class="card sc"><table><tr><th>Name</th><th>Serial</th><th>Stage</th><th>Client</th><th class="n">Cost</th><th>Source</th></tr>
  ${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.serial)}</td><td><span class="tag">${esc(r.stage)}</span></td><td>${esc(cname(r.client))}</td><td class="n">${R(r.cost)}</td><td class="mu">${r.src}</td></tr>`).join("")||"<tr><td colspan=6 class='mu'>No hardware tracked yet.</td></tr>"}</table></div>`;
};
binds.hwlife=()=>{$("#hw_sv").onclick=()=>{if(!$("#hw_n").value)return toast("Enter a name");
  db.assets.push({id:uid(),name:$("#hw_n").value,serial:$("#hw_s").value,stage:$("#hw_st").value,client:$("#hw_c").value,cost:+$("#hw_cost").value||0,date:$("#hw_d").value||today(),life:5,salvage:0});
  save();render();toast("Hardware saved to Fixed Assets")}};

