const mmLabel=id=>{for(const s of NAV_CATALOG){const x=s[1].find(i=>i[0]===id);if(x)return x[1]}return id};
/* Pages that a page links to, read from the page itself (rendered with no record open, so nothing is changed). */
const mmRelated=id=>{
  if(id==="navmod"||id==="mindmap")return[];
  if(id==="help")return["mindmap"];
  const keep=ed;let html="";
  try{ed=null;html=String((views[id]||(()=>""))())}catch(e){html=""}finally{ed=keep}
  return[...new Set([...html.matchAll(/go\(\\?['"]([a-z0-9_]+)\\?['"]/g)].map(m=>m[1]))].filter(x=>x!==id&&views[x]&&x!=="navmod"&&x!=="mindmap"&&x!=="help");
};
const mmRows=()=>{
  const r=[["Level","Section","Page / Node","Nav ID","Type","Description","Related modules","Side panel"]];
  r.push([0,"IT-Tech Business Manager","IT-Tech Business Manager","","App","Browser-based business manager for an IT services company. Data stays in this browser.","",""]);
  NAV_CATALOG.forEach(([sec,items])=>{
    r.push([1,sec,sec,"","Section",MM_SEC[sec]||"","",""]);
    items.forEach(([id,label])=>{
      r.push([2,sec,label,id,"Page",MOD_INFO[id]||"",mmRelated(id).map(mmLabel).join("; "),navOn(id)?"On":"Off"]);
      (MOD_SUB[id]||[]).forEach(([n,d])=>r.push([3,sec,n,id,"Feature",d,"",""]));
    });
  });
  return r;
};
