  document.querySelectorAll("[data-hp]").forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.hp)});
  ["hp_csv","hp_csv2"].forEach(id=>{if($("#"+id))$("#"+id).onclick=window.mmDownload});
