/* --- Timesheets week view --- */
views.timesheets=()=>{
  const rows=db.jobs.flatMap(j=>(j.time||[]).map(t=>({...t,j})));
  const unb=rows.filter(t=>!t.b);
  const byDay={};rows.forEach(t=>{byDay[t.d]=(byDay[t.d]||0)+(+t.hrs||0)});
  const last7=[...Array(7)].map((_,i)=>addDays(today(),-i)).reverse();
  return`<h2>Tasks &amp; Timesheets</h2>
  <div class="grid"><div class="card kpi"><span>Hours logged</span><b>${sum(rows,t=>t.hrs)}h</b></div>
  <div class="card kpi"><span>Unbilled</span><b>${sum(unb,t=>t.hrs)}h</b></div>
  <div class="card kpi"><span>Billable value</span><b>${R(sum(unb,t=>t.hrs)*(+db.set.rate||0))}</b></div>
  <div class="card kpi"><span>Labour cost</span><b>${R(sum(rows,t=>t.hrs)*(+db.set.costRate||0))}</b></div></div>
  <div class="card"><h3>Last 7 days</h3><div class="bars">${last7.map(d=>{const h=byDay[d]||0,max=Math.max(1,...Object.values(byDay));
    return`<div><i style="height:${h/max*100}%;background:var(--ac)"></i>${d.slice(5)}<br>${h}h</div>`}).join("")}</div></div>
  <div class="card"><h3>Log time</h3>
  <div class="row"><label>Job<select id="ts_j">${db.jobs.filter(j=>j.status!=="Done").map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join("")||"<option value=''>No open jobs</option>"}</select></label>
  ${inp("ts_d","Date",today(),"date")}${inp("ts_h","Hours",1,"number")}<label>Billable<input type="checkbox" id="ts_bill" style="width:auto" checked></label>
  ${inp("ts_n","Work done","")}<button class="p f0" id="ts_a">Log</button></div></div>
  <div class="card sc"><table><tr><th>Date</th><th>Job</th><th>Note</th><th class="n">Hours</th><th></th><th></th></tr>
  ${rows.sort((a,b)=>b.d.localeCompare(a.d)).slice(0,120).map(t=>`<tr><td>${t.d}</td><td>${esc(t.j.title)}</td><td>${esc(t.n||"")}</td><td class="n">${t.hrs}h</td>
  <td>${t.b?'<span class="tag ok">Billed</span>':'<span class="tag wa">Unbilled</span>'}</td>
  <td><button class="d" onclick="(function(){const j=db.jobs.find(x=>x.id==='${t.j.id}');j.time=j.time.filter(x=>x.id!=='${t.id}');save();render()})()">✕</button></td></tr>`).join("")||"<tr><td colspan=6 class='mu'>No time yet.</td></tr>"}</table></div>
  <div class="card"><button onclick="go('proj')">Bill from project</button> <button onclick="go('work')">Workspace</button> <button onclick="go('capacity')">Capacity</button></div>`;
};
binds.timesheets=()=>{$("#ts_a").onclick=()=>{const id=$("#ts_j").value,h=parseFloat($("#ts_h").value);if(!id||!(h>0))return toast("Choose job and hours");
  const j=db.jobs.find(x=>x.id===id);j.time=j.time||[];j.time.push({id:uid(),d:$("#ts_d").value||today(),hrs:h,n:$("#ts_n").value||"",b:false});
  actLog("time","Logged "+h+"h on "+j.title,j.id);save();render();toast("Time logged")}};

/* --- Capacity heatmap --- */
views.capacity=()=>{
  const cap=+db.set.cap||40;
  const open=db.jobs.filter(j=>j.status!=="Done");
  const load={};
  open.forEach(j=>{const k=j.who||"";load[k]=load[k]||{h:0,n:0,urgent:0};load[k].h+=j.hrs||0;load[k].n++;if(j.pri==="Urgent")load[k].urgent++});
  const util=h=>h/cap;
  return`<h2>Resource Capacity Planning</h2>
  <div class="grid"><div class="card kpi"><span>Weekly capacity</span><b>${cap}h</b></div>
  <div class="card kpi"><span>Open tasks</span><b>${open.length}</b></div>
  <div class="card kpi"><span>Hours backlog</span><b>${sum(Object.values(load),x=>x.h)}h</b></div>
  <div class="card kpi"><span>People loaded</span><b>${Object.keys(load).length}</b></div></div>
  <div class="card"><table><tr><th>Person</th><th class="n">Tasks</th><th class="n">Urgent</th><th class="n">Hours</th><th class="n">Weeks</th><th class="n">Util.</th><th style="width:28%">Load</th></tr>
  ${Object.entries(load).sort((a,b)=>b[1].h-a[1].h).map(([k,a])=>{const u=util(a.h);
    return`<tr><td>${esc(who(k))}</td><td class="n">${a.n}</td><td class="n">${a.urgent}</td><td class="n">${a.h}h</td><td class="n">${(a.h/cap).toFixed(1)}</td>
    <td class="n ${u>1?"neg":""}">${Math.round(u*100)}%</td>
    <td><div style="background:var(--ln);border-radius:5px;height:10px"><div style="width:${Math.min(100,u*100)}%;height:10px;border-radius:5px;background:${u>1?"var(--rd)":u>0.8?"var(--ac)":"var(--gn)"}"></div></div></td></tr>`}).join("")||"<tr><td colspan=7 class='mu'>Assign jobs to people in Directory to see load.</td></tr>"}</table>
  <p class="mu">Capacity from Pricing / Settings. Over 100% means more than one week of backlog at standard hours.</p>
  <button onclick="go('pricing')">Change capacity</button> <button onclick="go('jobs')">Jobs</button> <button onclick="go('dispatch')">Dispatches</button> <button onclick="go('sup')">Directory</button></div>`;
};
binds.capacity=()=>{};

