/* --- Roles interactive checklist --- */
views.roles=()=>{
  const roles=db.set.roles||[];
  const byDept={};
  roles.forEach(r=>{(byDept[r.dept||"General"]=byDept[r.dept||"General"]||[]).push(r)});
  const active=db.set.activeRole||"";
  const roleName=id=>(roles.find(r=>r.id===id)||{}).name||"—";
  const people=(typeof labour==="function"?labour():db.contacts.filter(c=>typeof isLab==="function"?isLab(c.type):true)).slice().sort((a,b)=>a.name.localeCompare(b.name));
  const assigned=people.filter(p=>p.sysRole).length;
  const roleOpts=(cur)=>`<option value="">— none —</option>`+roles.map(r=>`<option value="${r.id}" ${cur===r.id?"selected":""}>${esc(r.name)}</option>`).join("");
  return`<h2>User Roles &amp; Permissions</h2>
  <div class="grid">
    <div class="card kpi"><span>Roles defined</span><b>${roles.length}</b></div>
    <div class="card kpi"><span>Directory people</span><b>${people.length}</b></div>
    <div class="card kpi"><span>With a role assigned</span><b>${assigned}</b></div>
    <div class="card kpi"><span>Active panel preset</span><b>${esc((roles.find(r=>r.id===active)||{}).name||"None")}</b></div>
  </div>
  <div class="card">
    <p>Assign system roles to people in the <b>Directory</b> (staff &amp; freelancers). Applying a role as a <b>panel preset</b> shows/hides side-panel modules for this browser session.</p>
    <div class="row"><button class="p f0" onclick="go('sup')">Open Directory</button>
    <button class="f0" onclick="go('navmod')">Side panel modules</button>
    <button class="f0" id="role_reset">Reset role catalogue</button>
    <button class="f0" onclick="go('audit')">Audit log</button></div>
  </div>

  <div class="card"><h3>Directory people — role assignment</h3>
  ${people.length?`<div class="sc"><table>
  <tr><th>Name</th><th>Type</th><th>Contact</th><th>System role</th><th></th></tr>
  ${people.map(p=>`<tr>
    <td><b>${esc(p.name)}</b>${p.role?`<br><span class="mu">${esc(p.role)}</span>`:""}<br><span class="mu">${esc(p.spec||p.skills||"")}</span></td>
    <td>${esc(p.type||"")}<br><span class="mu">${p.status||""}</span></td>
    <td>${esc(p.email||"")}<br>${esc(typeof phTxt==="function"?phTxt(p):(p.phone||""))}</td>
    <td><select data-assign="${p.id}">${roleOpts(p.sysRole||"")}</select>
    ${p.sysRole?`<br><span class="tag">${esc(roleName(p.sysRole))}</span>`:""}</td>
    <td><button data-role="${p.sysRole||""}" ${p.sysRole?"":"disabled"}>Apply their role to panel</button>
    <button class="f0" onclick="go('sup',{c:db.contacts.find(z=>z.id=='${p.id}')})">Edit in Directory</button></td>
  </tr>`).join("")}
  </table></div>
  <p class="mu" style="margin-top:8px">Companies and pure suppliers stay in Directory without a login role. Only staff &amp; freelancers appear here.</p>`
  :`<p class="mu">No staff or freelancers in the Directory yet. <a href="#" onclick="go('sup');return false">Add technicians, employees and contractors</a> first, then assign roles here.</p>`}
  </div>

  ${Object.entries(byDept).map(([dept,list])=>`<div class="card"><h3>${esc(dept)} — role catalogue</h3>
  <div class="sc"><table><tr><th>Role</th><th>Description</th><th>People</th><th>Modules</th><th></th></tr>
  ${list.map(r=>{
    const who=people.filter(p=>p.sysRole===r.id);
    return`<tr>
    <td><b>${esc(r.name)}</b><br><span class="mu">${esc(r.id)}</span>${active===r.id?' <span class="tag ok">Active preset</span>':""}</td>
    <td>${esc(r.desc||"")}</td>
    <td>${who.length?who.map(p=>esc(p.name)).join(", "):"<span class='mu'>—</span>"}</td>
    <td class="mu" style="max-width:220px">${(r.perms||[]).includes("*")?"All modules (*)":(r.perms||[]).join(", ")}</td>
    <td><button data-role="${r.id}">Apply as panel preset</button></td>
  </tr>`}).join("")}
  </table></div></div>`).join("")}

  <div class="card"><h3>Permission guide</h3>
  <ul>
    <li><b>Project Manager</b> – projects, capacity, pipelines, clients, limited stock/shipping.</li>
    <li><b>Field Supervisor</b> – dispatches, technicians’ workspace, capacity.</li>
    <li><b>Procurement / Storekeeper</b> – RFQs, POs, inventory, suppliers, plus the calendar for RFQ and delivery dates.</li>
    <li><b>Service Desk</b> – front-line jobs and calendar without full finance.</li>
    <li><b>Network / IoT specialists</b> – technical delivery modules.</li>
    <li><b>Account Manager</b> – relationship and commercial follow-up.</li>
    <li><b>Accountant / Financial Controller</b> – finance stack (controller adds POs and stock), plus the calendar for invoice and quote dates.</li>
    <li><b>Read-only Auditor</b> – reports and audit without operational panels.</li>
    <li><b>Office Administrator</b> – directory, calendar, light CRM support.</li>
  </ul>
  <p class="mu">Assigning a role to a Directory person stores it on their contact record. Applying a panel preset only changes this browser’s visible modules.</p>
  </div>`;
};
binds.roles=()=>{
  const applyPreset=id=>{
    const r=(db.set.roles||[]).find(x=>x.id===id);if(!r)return toast("No role selected");
    if(!db.set.nav)db.set.nav={};
    const star=r.perms&&r.perms.includes("*");
    (NAV_CATALOG||[]).forEach(([,items])=>items.forEach(([mid])=>{
      if(typeof NAV_LOCKED!=="undefined"&&NAV_LOCKED.has(mid))db.set.nav[mid]=true;
      else if(star)db.set.nav[mid]=true;
      else db.set.nav[mid]=!r.perms||r.perms.includes(mid)||["dash","help"].includes(mid);
    }));
    db.set.activeRole=r.id;save();if(typeof applyNav==="function")applyNav();render();toast("Panel preset: "+r.name);
  };
  document.querySelectorAll("[data-role]").forEach(b=>{
    if(b.disabled)return;
    b.onclick=()=>{const id=b.dataset.role;if(id)applyPreset(id)};
  });
  document.querySelectorAll("[data-assign]").forEach(sel=>{
    sel.onchange=()=>{
      const c=db.contacts.find(x=>x.id===sel.dataset.assign);if(!c)return;
      c.sysRole=sel.value||"";
      save();render();toast(c.sysRole?"Assigned "+((db.set.roles||[]).find(r=>r.id===c.sysRole)||{}).name+" to "+c.name:"Cleared role for "+c.name);
    };
  });
  if($("#role_reset"))$("#role_reset").onclick=()=>{
    if(!confirm("Replace role catalogue with the full default list? Assignments on Directory people are kept if role ids still exist."))return;
    db.set.roles=[{id:"admin",name:"Administrator",dept:"Management",desc:"Full system access, backups, panel modules, all financials and settings.",perms:["*"]},{id:"pm",name:"Project Manager",dept:"Projects",desc:"Own projects end-to-end: tasks, capacity, pipelines, client liaison, limited billing.",perms:["dash","cal","clients","jobs","dispatch","work","proj","timesheets","capacity","pipeline","quotes","deals","stock","ship","rep","help"]},{id:"tech",name:"Technician",dept:"Field",desc:"Jobs, dispatches, timesheets, stock issue, device notes.",perms:["dash","cal","clients","jobs","dispatch","work","timesheets","stock","iot","hwlife","ship","help"]},{id:"field_sup",name:"Field Supervisor",dept:"Field",desc:"Oversee technicians, urgent dispatches, workspace and capacity.",perms:["dash","cal","clients","jobs","dispatch","work","timesheets","capacity","stock","ship","sup","rep","help"]},{id:"sales",name:"Sales Executive",dept:"Sales",desc:"Clients, quotations, pipeline, commercial project data.",perms:["dash","cal","clients","quotes","deals","proj","svcdir","pricing","rep","help"]},{id:"am",name:"Account Manager",dept:"Sales",desc:"Client relationships, SLA follow-up, quotes and project status.",perms:["dash","cal","clients","quotes","deals","jobs","proj","work","rep","help"]},{id:"accounts",name:"Accountant",dept:"Finance",desc:"Invoices, payments, ledger, tax, banking and reports.",perms:["dash","cal","inv","quotes","acc","fin","gl","tax","bank","assets","fc","rep","audit","help"]},{id:"fin_ctrl",name:"Financial Controller",dept:"Finance",desc:"Full finance stack plus fixed assets and cash forecast oversight.",perms:["dash","cal","inv","quotes","acc","fin","gl","tax","bank","assets","fc","rep","audit","pos","stock","help"]},{id:"procurement",name:"Procurement Officer",dept:"Supply",desc:"RFQs, purchase orders, suppliers and receiving stock.",perms:["dash","cal","rfq","pos","stock","sup","vendors","ship","hwlife","rep","help"]},{id:"store",name:"Storekeeper",dept:"Supply",desc:"Inventory movements, low-stock, shipments, basic PO receive.",perms:["dash","cal","stock","pos","ship","sup","hwlife","help"]},{id:"servicedesk",name:"Service Desk Agent",dept:"Support",desc:"Log jobs, client contact, calendar and basic quotes.",perms:["dash","cal","clients","jobs","dispatch","work","quotes","svcdir","help"]},{id:"neteng",name:"Network Engineer",dept:"Technical",desc:"Projects, installs, hardware lifecycle, inventory for network gear.",perms:["dash","cal","clients","jobs","dispatch","proj","pipeline","work","stock","hwlife","iot","timesheets","help"]},{id:"iot",name:"IoT Specialist",dept:"Technical",desc:"Device nodes, hardware, install pipelines and field jobs.",perms:["dash","cal","clients","jobs","dispatch","iot","hwlife","proj","pipeline","stock","timesheets","help"]},{id:"office",name:"Office Administrator",dept:"Admin",desc:"Directory, calendar, light clients and document support.",perms:["dash","cal","clients","sup","fld","help","mindmap"]},{id:"auditor",name:"Read-only Auditor",dept:"Governance",desc:"Reports, audit log and accounting views without operational edits (panel limited).",perms:["dash","rep","audit","acc","gl","fin","tax","help"]}];
    save();render();toast("Role catalogue reset");
  };
};



