/* --- Dashboard activity strip (wrap) --- */
const _dashV=views.dash;
views.dash=()=>{
  const base=_dashV();
  const recent=acts(()=>true,8);
  return base+`<div class="card"><h3>Recent activity</h3>
  ${recent.map(a=>`<p><span class="mu">${a.date} ${a.time||""}</span> · <span class="tag">${esc(a.type)}</span> ${esc(a.title)}</p>`).join("")||"<p class='mu'>Use clients, jobs, stock and banking — activity will show here.</p>"}
  <button onclick="go('audit')">Audit log</button> <button onclick="go('navmod')">Panel modules</button></div>`;
};

/* --- Dashboard: coming up (next 7 days, from the calendar) --- */
const _dashCalV=views.dash,_dashCalB=binds.dash;
views.dash=()=>{
  const base=_dashCalV();
  const t=today(),end=addDays(t,7);
  const keep=new Set(["job","dispatch","project-start","project-end","milestone","review","deal","client-review","invoice-due","quote-expiry","rfq-need","ship-eta","warranty","iot-warranty","note"]);
  const up=calCollect(true).filter(e=>keep.has(e.type)&&e.date>=t&&e.date<=end)
    .sort((a,b)=>a.date.localeCompare(b.date)||(a.time||"99:99").localeCompare(b.time||"99:99"));
  const dLab=ds=>ds===t?"Today":calParse(ds).toLocaleDateString("en-ZA",{weekday:"short",day:"numeric",month:"short"});
  const card=`<div class="card" id="dash_up"><h3>Coming up – next 7 days</h3>${up.length?`<div class="sc"><table>
    ${up.slice(0,10).map(e=>`<tr><td>${dLab(e.date)}</td><td><span class="tag">${esc(e.type)}</span></td><td>${esc(calLabel(e))}</td><td>${calOpenBtn(e)}</td></tr>`).join("")}
    </table></div>${up.length>10?`<p class="mu">+${up.length-10} more on the calendar</p>`:""}`:"<p class='mu'>Nothing scheduled in the next 7 days.</p>"}
    <button class="f0" onclick="go('cal')">Open calendar</button></div>`;
  const marker='<div class="card"><h3>Recent activity</h3>';
  return base.includes(marker)?base.replace(marker,card+marker):base+card;
};
binds.dash=()=>{
  if(_dashCalB)_dashCalB();
  document.querySelectorAll("#dash_up [data-open]").forEach(b=>b.onclick=e=>{e.stopPropagation();calGoEvent(b.dataset.open,b.dataset.oid)});
};

render();
